                    d = t[(j + 1) % n]
                    delta = dist[a][c] + dist[b][d] - dab - dist[c][d]

                    if delta < -1e-12:
                        t[i + 1:j + 1] = reversed(t[i + 1:j + 1])
                        for q in range(i + 1, j + 1):
                            pos[t[q]] = q
                        changed = True
