                                removed_delta
                                + dist[u][first]
                                + dist[last][w]
                                - dist[u][w]
                            )

                            if delta < best_delta:
                                best_delta = delta
                                best_c = c

                    if best_c >= 0:
                        del t[i:i + size]
                        j = t.index(best_c)
                        t[j:j] = block
                        changed = True
                        break

                if changed:
