    start_ids.update([0, n // 4, n // 2, 3 * n // 4, n - 1])

    for s in sorted(start_ids):
        candidates.append(nearest_neighbor(s))

    # Farthest-point and cheapest-insertion seeds.
    for mode in range(3):
        candidates.append(insertion_seed(radial[0], mode))
        if mode < 2:
